{"fw_ld6_walk_other_1_0117","walk",2,"reg=civilian,family,worker,rescue|r1=civilian,family,worker,rescue|r2=rescue|mood=sad",{1,"You doing okay?",2,"I'm walking, and I'm trying not to think",1,"About what",2,"About whether I'm gonna go back for the others"}},
