{"fw_ld6_walk_raw_1_0008","walk",3,"reg=civilian,worker|mood=angry|world=road",{1,"Quit stepping on the heels of my shoes!",2,"I'm not",1,"You are, you're gonna wear a hole in them",3,"Nobody's stepping on anything, it's the road"}},
{"fw_ld6_walk_raw_1_0009","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I can't feel my face from the sun",2,"It's still there",1,"Is it? Check, tell me what's on it"}},
{"fw_ld6_walk_raw_1_0010","walk",2,"reg=civilian,worker|mood=sad",{1,"I used to run five miles every morning and now I can't walk two",2,"It's the pack",1,"It's the bullshit is what it is, I'm out of shape"}},
