{"fw_ld6_walk_raw_1_0013","walk",3,"reg=civilian,family,worker,rescue|mood=sad",{1,"Do you ever get sick of being brave?",2,"I'm not brave",1,"You're doing it",3,"We're all doing it, nobody's brave, we're just walking"}},
{"fw_ld6_walk_raw_1_0014","walk",2,"reg=civilian,worker|mood=funny|world=fence",{1,"There's a Wal-Mart bag stuck in that fence, and it's the most beautiful thing I've seen all day",2,"It's trash",1,"It's trash that used to be a Wal-Mart, think about that"}},
