{"fw_ld6_walk_raw_1_0016","walk",2,"reg=civilian,worker|mood=grim",{1,"I don't want to go in that town",2,"We have to",1,"I know we have to, I'm saying I don't want to, I'm allowed to say it",2,"Say it, then walk"}},
{"fw_ld6_walk_raw_1_0017","walk",3,"reg=civilian,worker|mood=angry",{1,"Whose idea was this walk anyway?",2,"Yours",1,"It was not",3,"It was Walt's, and Walt's not here, so shut up and carry your bag"}},
{"fw_ld6_walk_raw_1_0018","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"If I find a vending machine I'm shooting it open",2,"It'll be empty",1,"It won't be empty, there'll be one Snickers, I can feel it"}},
