{"fw_ld6_walk_raw_1_0028","walk",2,"reg=law,swat|mood=angry",{1,"I'm so damn tired of walking",2,"We've walked four miles",1,"I used to drive four miles to get a donut",2,"And now you walk four miles for nothing"}},
