{"fw_ld6_walk_raw_1_0030","walk",2,"reg=law,swat|mood=angry|world=building",{1,"If I see one more mailbox I'm gonna shoot it",2,"It's a mailbox",1,"It's been following us, it's the same one",2,"Put the gun away"}},
