{"fw_ld6_walk_raw_1_0042","walk",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"I want a cold beer so bad I can feel it in my teeth",2,"Quit it",1,"A cold one, with a lime",3,"There's no lime in Kentucky, shut up and walk"}},
