{"fw_ld6_walk_raw_1_0093","walk",2,"reg=civilian,family,worker,rescue|mood=fear|world=door,window",{1,"There's a house, big one, look, doors open, curtains moving",2,"Don't",1,"I'm just LOOKING",2,"Keep walking, quick, quick, don't stop"}},
{"fw_ld6_walk_raw_1_0094","walk",2,"reg=civilian,worker|mood=funny",{1,"I'd give a month's pay for a goddamn bench",2,"A bench?",1,"A bench, a stump, a tractor tire, anything I can put my ass on!"}},
{"fw_ld6_walk_raw_1_0095","walk",3,"reg=civilian,family,worker,rescue|mood=sad|world=road",{1,"This is the road we took to the lake, remember, with the radio on",2,"Don't",1,"I'm just saying, it's the same-- it looks the same",3,"It's not the same, nothing's the same"}},
{"fw_ld6_walk_raw_1_0096","walk",2,"reg=civilian,worker|hour=9,19|mood=angry",{1,"I told you we should've left at dawn!",2,"You said noon",1,"I said dawn, I said DAWN, I said it three times"}},
{"fw_ld6_walk_raw_1_0097","walk",2,"reg=civilian,family,worker,rescue|mood=fear",{1,"Is that smoke? Over there, over the hill?",2,"Could be anything",1,"Could be someone, could be a house, could be--",2,"Stop, don't talk yourself into it"}},
{"fw_ld6_walk_raw_1_0098","walk",3,"reg=civilian,worker|mood=funny",{1,"If I see one more cow I'm gonna lose it",2,"They're cows",1,"They're looking at us!",3,"They look at everybody, it's what they do"}},
{"fw_ld6_walk_raw_1_0099","walk",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"Hey, you okay? You've gone all quiet",2,"I'm fine, I'm just thinking of home",1,"Me too, it's the walking, it makes you think"}},
{"fw_ld6_walk_raw_1_0100","walk",2,"reg=civilian,worker|mood=angry",{1,"Don't walk behind me like that, I can hear you breathing",2,"I'm walking",1,"I know you're walking, I'm saying quit breathing on my neck!"}},
{"fw_ld6_walk_raw_1_0101","walk",3,"reg=civilian,family,worker,rescue|mood=fear|world=road",{1,"Whoa, whoa, hold it, hold it, there's something in the road",2,"What is it?",1,"I don't-- it's a bag, it's a bag, okay, it's a bag",3,"Walk around it, don't touch it"}},
{"fw_ld6_walk_raw_1_0102","walk",2,"reg=civilian,worker|mood=sad",{1,"I used to run this stretch every morning, I thought I was in shape",2,"You were",1,"Nobody's in shape for this, Jesus Christ"}},
{"fw_ld6_walk_raw_1_0103","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Ow! Dammit! Rock!",2,"Where?",1,"In my shoe, it's been there for a mile, I was ignoring it!"}},
{"fw_ld6_walk_raw_1_0104","walk",3,"reg=civilian,worker|mood=angry|world=summer",{1,"How the hell is it still this hot at six?!",2,"It's summer",1,"I KNOW it's summer, I'm asking God, not you",3,"God's busy"}},
{"fw_ld6_walk_raw_1_0105","walk",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"I'm so thirsty I'd drink out of that puddle",2,"Don't",1,"I'm thinking about it, I'm thinking real hard"}},
{"fw_ld6_walk_raw_1_0106","walk",2,"reg=law,swat|mood=angry",{1,"Eyes up, hands off your weapons, this isn't a damn parade",2,"Nobody's marching",1,"Then walk like you mean it!"}},
{"fw_ld6_walk_raw_1_0107","walk",3,"reg=law,swat|mood=funny",{1,"If I step in one more cow pie I'm writing the cow a ticket",2,"For what?",1,"Public littering!",3,"It's a big ticket"}},
{"fw_ld6_walk_raw_1_0108","walk",2,"reg=law,swat|mood=sad|world=road",{1,"We used to patrol this road in a car, you remember, windows down",2,"I remember",1,"I never knew how long it was until I had to walk it"}},
{"fw_ld6_walk_raw_1_0109","walk",2,"reg=military|mood=angry",{1,"Close it up, you're twenty meters back, you want a medal for being slow?",2,"My feet are bleeding",1,"Then bleed faster, we're losing light!"}},
{"fw_ld6_walk_raw_1_0110","walk",3,"reg=military,elite|mood=funny",{1,"Ranger buddy, you're walking like you just got shot",2,"Feels like it",3,"Feels like it, feels like a hundred bucks, move your ass"}},
{"fw_ld6_walk_raw_1_0111","walk",2,"reg=military|mood=grim",{1,"Rest stop in twenty, then we push through",2,"Push through to where?",1,"Wherever the map says, it's your map, you tell me"}},
{"fw_ld6_walk_raw_1_0112","walk",3,"reg=outlaw,raider,gang,club,crime,prison|mood=angry",{1,"Shut your mouth, you talk too goddamn much when we walk",2,"I'm talking to myself",1,"Then talk to yourself QUIETLY, jackass!",3,"Nervous, leave 'em be"}},
{"fw_ld6_walk_raw_1_0113","walk",2,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"Hey, I found a shortcut!",2,"It's a swamp",1,"It's a SHORT swamp, you big baby"}},
{"fw_ld6_walk_raw_1_0114","walk",2,"reg=outlaw,raider,gang,club,crime,prison|mood=angry",{1,"I'm not walking another step until somebody gives me a drink",2,"Walk or don't, I'll leave you here",1,"You wouldn't",2,"Try me, genius"}},
{"fw_ld6_walk_raw_1_0115","walk",2,"reg=outlaw,raider,gang,club,crime,prison|mood=sad|world=hot",{1,"It's like a funeral, all of us dragging along, nobody talking",2,"Then talk",1,"About what? The weather? It's hot, it's fucking hot, there, I said it"}},
